import { Container, Button } from '@/components/ui';
import { ArrowRight, ArrowUp, ArrowUpRight, MapPin } from 'lucide-react';
import BrandMark from '@/site/brand';
import LanguageSwitcher from '@/components/site/language-switcher';
import { site } from '@/site/data';
import { cn } from '@/lib/utils';

/* @slot flink */
const footLink = 'text-small text-muted-foreground transition-colors hover:text-foreground';
/* @end */

/* @slot fnav md */
function FooterNav({ className }: { className?: string }) {
  const links = site.pages.length > 1 ? site.pages : site.navigation;
  return (
    <ul className={cn('flex flex-wrap gap-x-5 gap-y-2.5 md:flex-col md:flex-nowrap md:gap-3', className)}>
      {links.map((link) => (<li key={link.href}><a className={footLink} href={link.href}>{link.label}</a></li>))}
    </ul>
  );
}
/* @end */

export default function SiteFooter() {
  return (
    <footer className="border-t border-border bg-background">
      <Container className="flex flex-col items-center gap-6 py-14 text-center">
        <BrandMark />
        {site.description && <p className="max-w-md text-small text-muted-foreground">{site.description}</p>}
        <nav aria-label={site.labels.pages}><FooterNav className="md:flex-row md:flex-wrap md:justify-center md:gap-x-7" /></nav>
      </Container>
      <Container className="flex flex-col items-center gap-3 border-t border-border py-6 text-center sm:flex-row sm:justify-center sm:gap-6">
        <p className="text-small text-muted-foreground">© {site.year} {site.name}. {site.labels.rights}.</p>
        <LanguageSwitcher />
      </Container>
    </footer>
  );
}

import { Container, Button } from '@/components/ui';
import { ArrowRight, ArrowUp, ArrowUpRight, MapPin } from 'lucide-react';
