import { cn } from '@/lib/utils';

/* @slot flink */
const footLink = 'text-small text-foreground/75 underline-offset-4 transition-colors hover:text-foreground hover:underline';
/* @end */

/* @slot fnav md */
function FooterNav({ className }: { className?: string }) {
  const links = site.pages.length > 1 ? site.pages : site.navigation;
  return (
    <ul className={cn('flex flex-wrap gap-x-5 gap-y-2.5 md:flex-col md:flex-nowrap md:gap-3', className)}>
      {links.map((link) => (<li key={link.href}><a className={footLink} href={link.href}>{link.label}</a></li>))}
    </ul>
  );
}
/* @end */

export default function SiteFooter() {
  return (
    <footer className="border-t border-border bg-muted/40">
      <Container className="flex flex-col items-center gap-7 py-14 text-center">
        <BrandMark />
        {site.contact.channels.length > 0 && (
          <ul className="flex flex-wrap justify-center gap-2">
            {site.contact.channels.map((channel) => (
              <li key={channel.label}>{channel.href ? <a className="inline-flex items-center gap-2 rounded-full border border-border bg-background px-4 py-2 text-small font-medium text-foreground transition-colors hover:border-primary hover:text-primary" href={channel.href}><span className="text-muted-foreground">{channel.label}</span>{channel.value}</a> : <span className="inline-flex gap-2 rounded-full border border-border px-4 py-2 text-small"><span className="text-muted-foreground">{channel.label}</span>{channel.value}</span>}</li>
            ))}
          </ul>
        )}
        <nav aria-label={site.labels.pages}><FooterNav className="md:flex-row md:flex-wrap md:justify-center md:gap-x-7" /></nav>
      </Container>
      <Container className="flex flex-col items-center gap-3 border-t border-border py-6 text-center sm:flex-row sm:justify-center sm:gap-6">
        <p className="text-small text-muted-foreground">© {site.year} {site.name}. {site.labels.rights}.</p>
        <LanguageSwitcher />
      </Container>
    </footer>
  );
}

import { Container, Button } from '@/components/ui';
