import BrandMark from '@/site/brand';
import LanguageSwitcher from '@/components/site/language-switcher';
import { site } from '@/site/data';
import { cn } from '@/lib/utils';

/* @slot flink */
const footLink = 'relative inline-block text-small text-muted-foreground transition-colors after:absolute after:-bottom-0.5 after:left-0 after:h-px after:w-full after:origin-right after:scale-x-0 after:bg-current after:transition-transform after:duration-300 hover:text-foreground hover:after:origin-left hover:after:scale-x-100';
/* @end */

/* @slot fnav md */
function FooterNav({ className }: { className?: string }) {
  const links = site.pages.length > 1 ? site.pages : site.navigation;
  return (
    <ul className={cn('flex flex-wrap gap-x-5 gap-y-2.5 md:flex-col md:flex-nowrap md:gap-3', className)}>
      {links.map((link) => (<li key={link.href}><a className={footLink} href={link.href}>{link.label}</a></li>))}
    </ul>
  );
}
/* @end */

export default function SiteFooter() {
  const channel = site.contact.channels[0];
  return (
    <footer className="border-t border-border bg-background">
      <Container className="flex flex-col items-center gap-6 py-16 text-center">
        <BrandMark />
        {site.description && <p className="max-w-xl font-heading text-h4 text-foreground">{site.description}</p>}
        <div className="flex flex-col items-center gap-3 sm:flex-row">
          {site.primaryAction && <Button asChild variant="primary"><a href={site.primaryAction.href}>{site.primaryAction.label}<ArrowRight /></a></Button>}
          {channel?.href && site.primaryAction?.href !== channel.href && <a className="text-small font-medium text-foreground underline-offset-4 hover:underline" href={channel.href}>{channel.value}</a>}
        </div>
      </Container>
      <Container className="flex flex-col items-center gap-6 border-t border-border py-8">
        <nav aria-label={site.labels.pages}><FooterNav className="md:flex-row md:flex-wrap md:justify-center md:gap-x-7" /></nav>
        <div className="flex flex-col items-center gap-3 sm:flex-row sm:gap-6"><p className="text-small text-muted-foreground">© {site.year} {site.name}. {site.labels.rights}.</p><LanguageSwitcher /></div>
      </Container>
    </footer>
  );
}

