                <a href={item.href} aria-current={active ? 'page' : undefined} className={cn('w-fit font-heading text-h3 leading-tight transition-colors', active ? 'text-primary' : 'text-foreground hover:text-primary')}>{item.label}</a>
              </SheetClose>
            );
          })}
        </nav>
        <div className="flex flex-col gap-5 border-t border-border px-gutter py-6">
          {site.contact.channels.length > 0 && (
            <ul className="flex flex-wrap gap-x-6 gap-y-2">
              {site.contact.channels.map((channel) => (<li key={channel.label} className="flex flex-col"><span className="text-small text-muted-foreground">{channel.label}</span>{channel.href ? <a className="text-small font-medium text-foreground hover:text-primary" href={channel.href}>{channel.value}</a> : <span className="text-small font-medium">{channel.value}</span>}</li>))}
            </ul>
          )}
          <div className="flex items-center justify-between gap-4">
            <LanguageSwitcher current={current} />
            {site.primaryAction && <Button asChild variant="primary"><a href={site.primaryAction.href}>{site.primaryAction.label}</a></Button>}
          </div>
        </div>
      </SheetContent>
    </Sheet>
  );
}

