          {site.primaryAction && <Button asChild variant="primary" className="w-full"><a href={site.primaryAction.href}>{site.primaryAction.label}</a></Button>}
          <LanguageSwitcher current={current} />
        </div>
      </SheetContent>
    </Sheet>
  );
}

